// [#436] AU AIREAT 2008.10.16
void LoadHostValue(PINIVALUE pwIniValue)
{
	int nTemp;

	if (pwIniValue->Key == L"HEALTHCHECKMODE")
	{
		MemSetInt(_MEM_FLD_INI_NETWORKINFO, _MEM_VAR_NETINFO_HEALTHYFLAG, GET_ENDISABLE_VALUE(pwIniValue->Values[0]));
	}
	else if (pwIniValue->Key == L"HEALTHCHECKINTERVAL")
	{
		nTemp = Asc2Int(pwIniValue->Values[0]);

		if (0 < nTemp && nTemp <= 24)
			MemSetInt(_MEM_FLD_INI_NETWORKINFO, _MEM_VAR_NETINFO_HSDELAYINT, nTemp);
	}
	else if (pwIniValue->Key == L"STATUSMONITORINGMODE")
	{
		MemSetInt(_MEM_FLD_INI_NETWORKINFO, _MEM_VAR_NETINFO_STATUSMONITORINGENABLE, GET_ENDISABLE_VALUE(pwIniValue->Values[0]));
	}
	else if (pwIniValue->Key == L"COMMUNICATIONHEADERMODE")
	{
		MemSetInt(_MEM_FLD_INI_NETWORKINFO, _MEM_VAR_NETINFO_COMMUNICATIONHEADERENABLE, GET_ENDISABLE_VALUE(pwIniValue->Values[0]));
	}
	else if (pwIniValue->Key == L"COMMUNICATIONID")
	{
		MemSetStr(_MEM_FLD_INI_NETWORKINFO, _MEM_VAR_NETINFO_COMMUNICATIONID, pwIniValue->Values[0]);
	}
	else if (pwIniValue->Key == L"CRCENABLE")
	{
		MemSetInt(_MEM_FLD_TCPIPINFO, _MEM_VAR_TCPIP_CRCENABLE, GET_ENDISABLE_VALUE(pwIniValue->Values[0]));
	}
	else if (pwIniValue->Key == L"HOSTIPADDRESS1")
	{
		MemSetStr(_MEM_FLD_TCPIPINFO, _MEM_VAR_TCPIP_HOST1NAME, pwIniValue->Values[0]);
	}
	else if (pwIniValue->Key == L"HOSTIPADDRESS2")
	{
		MemSetStr(_MEM_FLD_TCPIPINFO, _MEM_VAR_TCPIP_HOST2NAME, pwIniValue->Values[0]);
	}
	else if (pwIniValue->Key == L"HOSTPORT1")
	{
		nTemp = Asc2Int(pwIniValue->Values[0]);

		if (nTemp >= 0 && nTemp < 65536)
			MemSetInt(_MEM_FLD_TCPIPINFO, _MEM_VAR_TCPIP_HOST1PORTNO, nTemp);
	}
	else if (pwIniValue->Key == L"HOSTPORT2")
	{
		nTemp = Asc2Int(pwIniValue->Values[0]);

		if (nTemp >= 0 && nTemp < 65536)
			MemSetInt(_MEM_FLD_TCPIPINFO, _MEM_VAR_TCPIP_HOST2PORTNO, nTemp);
	}
	else if (pwIniValue->Key == L"HOSTPHONENUMBER1")
	{
		MemSetStr(_MEM_FLD_INI_NETWORKINFO, _MEM_VAR_NETINFO_PHONENODEFINE1, pwIniValue->Values[0]);
	}
	else if (pwIniValue->Key == L"HOSTPHONENUMBER2")
	{
		MemSetStr(_MEM_FLD_INI_NETWORKINFO, _MEM_VAR_NETINFO_PHONENODEFINE2, pwIniValue->Values[0]);
	}
	// [#RWC6-72] US William 2019.12.09 PAI INI file
	else if (pwIniValue->Key == L"HOSTURLSETUP")
	{
		MemSetInt(_MEM_FLD_TCPIPINFO, _MEM_VAR_TCPIP_ISHOSTUSEURL, GET_ENDISABLE_VALUE(pwIniValue->Values[0]));
	}
	else if (pwIniValue->Key == L"HOSTUSESSL")
	{
		MemSetInt(_MEM_FLD_TCPIPINFO, _MEM_VAR_TCPIP_SSLENABLE, GET_ENDISABLE_VALUE(pwIniValue->Values[0]));
	}
	else if (pwIniValue->Key == L"HOSTTLSVERSION")
	{
		if (pwIniValue->Values[0].CompareNoCase(L"SSLv3") == 0)
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_SSLVERSION, CONN_UPTO_SSL_V30);
		else if (pwIniValue->Values[0].CompareNoCase(L"TLSv1") == 0)
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_SSLVERSION, CONN_UPTO_TLS_V10);
		else if (pwIniValue->Values[0].CompareNoCase(L"TLSv11") == 0)
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_SSLVERSION, CONN_UPTO_TLS_V11);
		else if (pwIniValue->Values[0].CompareNoCase(L"TLSv12") == 0)
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_SSLVERSION, CONN_UPTO_TLS_V12);
		else if (pwIniValue->Values[0].CompareNoCase(L"TLSv13") == 0)
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_SSLVERSION, CONN_UPTO_TLS_V13);
		else if (pwIniValue->Values[0].CompareNoCase(L"SSLv3_cert") == 0)
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_SSLVERSION, CONN_UPTO_SSL_V30_USE_CERT);
		else if (pwIniValue->Values[0].CompareNoCase(L"TLSv1_cert") == 0)
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_SSLVERSION, CONN_UPTO_TLS_V10_USE_CERT);
		else if (pwIniValue->Values[0].CompareNoCase(L"TLSv11_cert") == 0)
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_SSLVERSION, CONN_UPTO_TLS_V11_USE_CERT);
		else if (pwIniValue->Values[0].CompareNoCase(L"TLSv12_cert") == 0)
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_SSLVERSION, CONN_UPTO_TLS_V12_USE_CERT);
		else if (pwIniValue->Values[0].CompareNoCase(L"TLSv13_cert") == 0)
			MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_SSLVERSION, CONN_UPTO_TLS_V13_USE_CERT);
	}
	else if (pwIniValue->Key == L"ROUTINGID")
	{
		MemSetStr(_MEM_FLD_APP_ATMINFO, _MEM_VAR_APP_ROUTINGID, pwIniValue->Values[0].Left(6));
	}
	else if (pwIniValue->Key == L"HOSTPROTOCOL")
	{
		if (pwIniValue->Values[0].CompareNoCase(L"STD1") == 0)
		{
			MemSetStr(_MEM_FLD_APP_ATMINFO, _MEM_VAR_APP_MSGTYPE, MSG_HYOSUNG_TYPE);
		}
		else if (pwIniValue->Values[0].CompareNoCase(L"CSP200") == 0)
		{
			MemSetStr(_MEM_FLD_APP_ATMINFO, _MEM_VAR_APP_MSGTYPE, MSG_CSP200_TYPE);
		}
		else if (pwIniValue->Values[0].CompareNoCase(L"STD3") == 0)
		{
			MemSetStr(_MEM_FLD_APP_ATMINFO, _MEM_VAR_APP_MSGTYPE, MSG_TRITON_TYPE);

#if (APP_CUSTOM_CIBC_MX)
			MemGetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_DCC_CUSTOMOPTION) == DCC_CUSTOMOPTION_BANSI;
#endif
		}
		else if (pwIniValue->Values[0].CompareNoCase(L"EPS") == 0)
		{
			MemSetStr(_MEM_FLD_APP_ATMINFO, _MEM_VAR_APP_MSGTYPE, MSG_EPS_TYPE);
		}
	}
	else if (pwIniValue->Key == L"TCPTYPE")
	{
		if (pwIniValue->Values[0].CompareNoCase(L"VISAFRAMED") == 0)
			MemSetInt(_MEM_FLD_TCPIPINFO, _MEM_VAR_TCPIP_TYPE, VISA_FRAMED_TCPIP);
		else if (pwIniValue->Values[0].CompareNoCase(L"STANDARD") == 0)
			MemSetInt(_MEM_FLD_TCPIPINFO, _MEM_VAR_TCPIP_TYPE, STANDARD_TCPIP);
		else if (pwIniValue->Values[0].CompareNoCase(L"ACK") == 0)
			MemSetInt(_MEM_FLD_TCPIPINFO, _MEM_VAR_TCPIP_TYPE, ACK_CONTROLLED_TCPIP);
		else if (pwIniValue->Values[0].CompareNoCase(L"VISANOENQ") == 0)
			MemSetInt(_MEM_FLD_TCPIPINFO, _MEM_VAR_TCPIP_TYPE, VISA_FRAMED_WITHOUT_ENQ_TCPIP);
	}
	else if (pwIniValue->Key == L"TERMINALSTATUS")
	{
		MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_TERMINAL_STATUS_FIELD_ENABLE, GET_ENDISABLE_VALUE(pwIniValue->Values[0]));
	}
	else if (pwIniValue->Key == L"HOSTERROR")
	{
		MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_REVERSAL_AT_HOSTERROR, GET_ENDISABLE_VALUE(pwIniValue->Values[0]));
	}
	else if (pwIniValue->Key == L"REVERSALOPTION")
	{
		MemSetInt(_MEM_FLD_OPTIONALSETTING_2, _MEM_VAR_OPT2_REASONFORREVERSAL_ENABLE, GET_ENDISABLE_VALUE(pwIniValue->Values[0]));
	}
	else if (pwIniValue->Key == L"EOTENQOPTION")
	{
		if (pwIniValue->Values[0].CompareNoCase(L"EOT Optional") == 0)
			MemSetStr(_MEM_FLD_INI_NETWORKINFO, _MEM_VAR_NETINFO_EOTCHECKMODE, EOT_OPTIONAL);
		else if (pwIniValue->Values[0].CompareNoCase(L"Only EOT Required") == 0)
			MemSetStr(_MEM_FLD_INI_NETWORKINFO, _MEM_VAR_NETINFO_EOTCHECKMODE, EOT_REQUIRED);
		else if (pwIniValue->Values[0].CompareNoCase(L"Only EOT Not Required") == 0)
			MemSetStr(_MEM_FLD_INI_NETWORKINFO, _MEM_VAR_NETINFO_EOTCHECKMODE, NO_EOT_REQUIRED);
		else if (pwIniValue->Values[0].CompareNoCase(L"Only ENQ Not Required") == 0)
			MemSetStr(_MEM_FLD_INI_NETWORKINFO, _MEM_VAR_NETINFO_EOTCHECKMODE, NO_ENQ_REQUIRED);
		else if (pwIniValue->Values[0].CompareNoCase(L"Both Not Required") == 0)
			MemSetStr(_MEM_FLD_INI_NETWORKINFO, _MEM_VAR_NETINFO_EOTCHECKMODE, NO_ENQ_EOT_REQUIRED);
	}
	// End of [#RWC6-72]
}
