			break;
		case _MEM_VAR_DEVINFO_DISPCASHCST4:
			nRet = (WORD)pCDUSP->CashUnit[4].ulUsrCount;
			break;

		case _MEM_VAR_CDMSP_NUMBEROFCST:
			nRet = (WORD)(pCDUSP->usCUNum - 1); //Reject box는 제외한다.
			break;
		case _MEM_VAR_CDMSP_CSTCOUNT1:
			nRet = (WORD)pCDUSP->CashUnit[1].ulCount;
			break;
		case _MEM_VAR_CDMSP_CSTCOUNT2:
			nRet = (WORD)pCDUSP->CashUnit[2].ulCount;
			break;
		case _MEM_VAR_CDMSP_CSTCOUNT3:
			nRet = (WORD)pCDUSP->CashUnit[3].ulCount;
			break;
		case _MEM_VAR_CDMSP_CSTCOUNT4:
			nRet = (WORD)pCDUSP->CashUnit[4].ulCount;
			break;
		case _MEM_VAR_CDMSP_CSTVALUE1:
			nRet = (WORD)pCDUSP->CashUnit[1].ulValues;
			break;
		case _MEM_VAR_CDMSP_CSTVALUE2:
			nRet = (WORD)pCDUSP->CashUnit[2].ulValues;
			break;
		case _MEM_VAR_CDMSP_CSTVALUE3:
			nRet = (WORD)pCDUSP->CashUnit[3].ulValues;
			break;
		case _MEM_VAR_CDMSP_CSTVALUE4:
			nRet = (WORD)pCDUSP->CashUnit[4].ulValues;
			break;
		case _MEM_VAR_CDMSP_CSTSTATUS1:
			nRet = (WORD)pCDUSP->CashUnit[1].usPStatus;
			break;
		case _MEM_VAR_CDMSP_CSTSTATUS2:
			nRet = (WORD)pCDUSP->CashUnit[2].usPStatus;
			break;
		case _MEM_VAR_CDMSP_CSTSTATUS3:
			nRet = (WORD)pCDUSP->CashUnit[3].usPStatus;
			break;
		case _MEM_VAR_CDMSP_CSTSTATUS4:
			nRet = (WORD)pCDUSP->CashUnit[4].usPStatus;
			break;
		case _MEM_VAR_CDMSP_FLAGENQSEND:
			nRet = (WORD)pCDUSP->bENQSend;
			break;
		case _MEM_VAR_CDMSP_CSTTYPE1:
			nRet = (WORD)pCDUSP->CashUnit[1].usType;
			break;
		case _MEM_VAR_CDMSP_CSTTYPE2:
			nRet = (WORD)pCDUSP->CashUnit[2].usType;
			break;
		case _MEM_VAR_CDMSP_CSTTYPE3:
			nRet = (WORD)pCDUSP->CashUnit[3].usType;
			break;
		case _MEM_VAR_CDMSP_CSTTYPE4:
			nRet = (WORD)pCDUSP->CashUnit[4].usType;
			break;
		// 2007.11.26 V01.02.19
		case _MEM_VAR_CDMSP_FLAGCDULOGBACKUP:
			nRet = (WORD)pCDUSP->bCDULogBackup;
			break;
		// [#513] [NH] KSK 2009.3.2 Low Sensor Check (EP 사양서 참조) (low 감지: 0, low sensor 미존재 or 미감지: 1)
		case _MEM_VAR_CDMSP_CST1_LOWSENSOR:
			nRet = (WORD)((pCDUSP->bySensorStatus[5] & 0x08)>>3);		// bit 3
			break;
		case _MEM_VAR_CDMSP_CST2_LOWSENSOR:
			nRet = (WORD)((pCDUSP->bySensorStatus[7] & 0x04)>>2);		// bit 2
			break;
		case _MEM_VAR_CDMSP_CST3_LOWSENSOR:
			nRet = (WORD)((pCDUSP->bySensorStatus[8] & 0x04)>>2);		// bit 2
			break;
		case _MEM_VAR_CDMSP_CST4_LOWSENSOR:
			nRet = (WORD)((pCDUSP->bySensorStatus[9] & 0x04)>>2);		// bit 2
			break;
		// end of [#513]
		// KSK 2009.3.30
		case _MEM_VAR_CDMSP_CST1_T_DISP_CNT:
			nRet = (WORD)pCDUSP->LastDispInfo[1].ulUsrCount;
			break;
		case _MEM_VAR_CDMSP_CST2_T_DISP_CNT:
			nRet = (WORD)pCDUSP->LastDispInfo[2].ulUsrCount;
			break;
		case _MEM_VAR_CDMSP_CST3_T_DISP_CNT:
