			break;
		case _MEM_VAR_CDMSP_CST4_T_DISP_CNT:
			nRet = (WORD)pCDUSP->LastDispInfo[4].ulUsrCount;
			break;
		case _MEM_VAR_CDMSP_CST1_T_REJ_CNT:
			nRet = (WORD)pCDUSP->LastDispInfo[1].ulRejCount;
			break;
		case _MEM_VAR_CDMSP_CST2_T_REJ_CNT:
			nRet = (WORD)pCDUSP->LastDispInfo[2].ulRejCount;
			break;
		case _MEM_VAR_CDMSP_CST3_T_REJ_CNT:
			nRet = (WORD)pCDUSP->LastDispInfo[3].ulRejCount;
			break;
		case _MEM_VAR_CDMSP_CST4_T_REJ_CNT:
			nRet = (WORD)pCDUSP->LastDispInfo[4].ulRejCount;
			break;
		// end of KSK 2009.3.30
		// [#534] AIREAT 2009.06.04
			// SKEW NOTE
		case _MEM_VAR_DEVINFO_RJTSKEW_CST1:
			nRet = (WORD)pCDUSP->LastDispInfo[1].ulSkewNote;
			break;
