			break;
		case _MEM_VAR_DEVINFO_RJTSKEW_CST4:
			nRet = (WORD)pCDUSP->LastDispInfo[4].ulSkewNote;
			break;
			// GAP TOO CLOSE NOTE
		case _MEM_VAR_DEVINFO_RJTGAPTOCLOSE_CST1:
			nRet = (WORD)pCDUSP->LastDispInfo[1].ulGapNote;
			break;
		case _MEM_VAR_DEVINFO_RJTGAPTOCLOSE_CST2:
