{
	CString	strTemp;
	if (nindex < 0 || nindex > ERRORSTACK_MAX_SIZE-1)	return L"";

	strTemp.Format(L"%S", pNVRam4->ErrSumStack[nindex].chErrorCode);
	return strTemp;
}

